export const WISDOM: Wisdom[] = W.map(([id, theme, text, by, source, kind, meaning, reflect, intent]) => ({ id, theme, text, by, source, kind, meaning, reflect, intent }));
export const themeName = (t: WisdomTheme) => WISDOM_THEMES.find(x => x[0] === t)![1];

/**
 * This morning's entry. The 12 themes take turns day by day so mornings vary, and each theme walks its own entries
 * in order and starts over, so it never runs out. Each agent starts at their own place.
 */
export function wisdomOfDay(y: number, m: number, d: number, agent = ''): Wisdom & { themeName: string } {
  const day = Math.floor(Date.UTC(y, m - 1, d) / 86_400_000);
  let h = 0; for (const ch of agent) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const [t, name] = WISDOM_THEMES[(day + h) % WISDOM_THEMES.length];
  const pool = WISDOM.filter(w => w.theme === t);
  return { ...pool[(Math.floor(day / WISDOM_THEMES.length) + h) % pool.length], themeName: name };
}
